reference_solution:
def process_special_string(s):
    result=[]
    for char in s:
        if char.isalpha():result.append(char)
        elif char=='*' and result:result.pop()
        elif char=='#':result.extend(result)
        elif char=='%':result.reverse()
    return ''.join(result)

